#include <linux/net.h>
#include <linux/netdevice.h>

int sit_init_net(struct net *net)
{
    struct sit_net *sit;

    sit = net_generic(net, sit_net_id);
    if (!sit)
        return -ENOMEM;

    sit->tunnels = NULL;
    sit->fb_tunnel_dev = NULL;

    if (sit->fb_tunnel_dev)
        return 0;

    sit->fb_tunnel_dev = alloc_netdev(0, "sit%d", NET_NAME_UNKNOWN, sit_setup);
    if (!sit->fb_tunnel_dev)
        return -ENOMEM;

    sit->fb_tunnel_dev->priv_flags |= IFF_ISATAP;
    sit->fb_tunnel_dev->rtnl_link_ops = &sit_link_ops;
    sit->fb_tunnel_dev->netdev_ops = &sit_netdev_ops;

    if (register_netdevice(sit->fb_tunnel_dev) < 0) {
        free_netdev(sit->fb_tunnel_dev);
        return -EIO;
    }

    return 0;
}

int sit_init_net(struct net *net)
{
    struct sit_net *sit = net_generic(net, sit_net_id);
    struct net_device *dev;
    int err;

    if (!sit)
        return -EINVAL;

    sit->tunnels = NULL;
    sit->fb_tunnel_dev = NULL;

    if (net->loopback_dev)
        sit->fb_tunnel_dev = net->loopback_dev;

    if (sit->fb_tunnel_dev)
        return 0;

    dev = alloc_netdev(0, "sit%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    dev->type = ARPHRD_SIT;
    dev->flags = IFF_NOARP;
    dev->mtu = 1500;

    err = register_netdev(dev);
    if (err) {
        free_netdev(dev);
        return err;
    }

    sit->fb_tunnel_dev = dev;
    return 0;
}

int sit_net_init(struct net *net)
{
    struct sit_net *sit = net_generic(net, sit_net_id);

    if (!sit)
        return -ENOMEM;

    sit->tunnels = NULL;
    sit->fb_tunnel_dev = NULL;

    if (net->loopback_dev)
        sit->fb_tunnel_dev = alloc_netdev(sizeof(struct ip_tunnel_net),
                                          "sit0", NET_NAME_UNKNOWN, ip_tunnel_setup);
    if (!sit->fb_tunnel_dev)
        return -ENOMEM;

    sit->fb_tunnel_dev->rtnl_link_ops = &sit_link_ops;
    sit->fb_tunnel_dev->type = ARPHRD_SIT;
    sit->fb_tunnel_dev->mtu = 1500;
    sit->fb_tunnel_dev->flags = IFF_NOARP;
    sit->fb_tunnel_dev->priv_flags = IFF_TUNNEL | IFF_SIT;

    if (register_netdevice(sit->fb_tunnel_dev) < 0) {
        free_netdev(sit->fb_tunnel_dev);
        return -EIO;
    }

    return 0;
}
